class WhoAmIView(APIView):
    def get(self, request):
        if request.user.is_authenticated:
            return Response({
                "authenticated": True,
                "username": request.user.username,
                "id": request.user.id,
            })
        return Response({
            "authenticated": False,
            "user": "AnonymousUser",
        })

class DebugAuthView(APIView):
    def get(self, request):
        return Response({
            "user_type": type(request.user).__name__,
            "user_repr": str(request.user),
            "auth_type": type(request.auth).__name__,
            "auth_repr": str(request.auth) if request.auth else None,
        })

class FlexibleAuthView(APIView):
    authentication_classes = [
        TokenAuthentication,      # اول توکن را امتحان کن
        SessionAuthentication,    # بعد نشست (برای Browsable API)
        BasicAuthentication,      # در نهایت Basic
    ]
    permission_classes = [IsAuthenticated]

    def get(self, request):
        return Response({"ok": True})
